/**
 * Managed machine-identity credential acquisition for inter-service calls.
 *
 * Generated for service-to-service callers declared with auth mode SERVICE.
 * The credential is the platform-managed machine identity, never a locally
 * signed application token.
 *
 * Strategy: oidc-client-credentials
 *
 * Auto-generated by datrix-codegen-typescript. Do not edit manually.
 */
import { readFileSync } from 'node:fs';

// Path to the machine service-account credentials the Zitadel provisioning
// init-job writes; the deployment-static token endpoint and Host header are
// injected as env vars at generation time.
const MACHINE_CREDENTIALS_FILE =
  process.env.IDENTITY_MACHINE_CREDENTIALS_FILE ?? '/machine-credentials/credentials.json';
const MACHINE_TOKEN_URL = process.env.IDENTITY_MACHINE_TOKEN_URL ?? '';
const MACHINE_HOST_HEADER = process.env.IDENTITY_MACHINE_HOST_HEADER ?? '';
const TOKEN_EXPIRY_SKEW_SECONDS = 30;

interface MachineCredentials {
  clientId: string;
  clientSecret: string;
  audience: string;
}

let cachedToken = '';
let cachedExpiry = 0;

function loadMachineCredentials(): MachineCredentials {
  let raw: unknown;
  try {
    raw = JSON.parse(readFileSync(MACHINE_CREDENTIALS_FILE, 'utf-8'));
  } catch (err) {
    throw new Error(
      `Machine credentials file '${MACHINE_CREDENTIALS_FILE}' could not be read: ${String(err)}. ` +
        'Ensure this service depends on the Zitadel init-job and mounts the shared volume.',
    );
  }
  const data = raw as Record<string, unknown>;
  const clientId = data.clientId;
  const clientSecret = data.clientSecret;
  const audience = data.audience;
  if (
    typeof clientId !== 'string' ||
    !clientId ||
    typeof clientSecret !== 'string' ||
    !clientSecret ||
    typeof audience !== 'string' ||
    !audience
  ) {
    throw new Error(
      `Machine credentials file '${MACHINE_CREDENTIALS_FILE}' is missing clientId/clientSecret/audience.`,
    );
  }
  return { clientId, clientSecret, audience };
}

function decodeTokenExpiry(token: string): number {
  const parts = token.split('.');
  if (parts.length !== 3) {
    return 0;
  }
  try {
    const payload = JSON.parse(Buffer.from(parts[1], 'base64url').toString('utf-8'));
    const exp = (payload as Record<string, unknown>).exp;
    return typeof exp === 'number' ? exp : 0;
  } catch {
    return 0;
  }
}

async function acquireZitadelMachineToken(): Promise<string> {
  const now = Date.now() / 1000;
  if (cachedToken && now < cachedExpiry - TOKEN_EXPIRY_SKEW_SECONDS) {
    return cachedToken;
  }
  if (!MACHINE_TOKEN_URL || !MACHINE_HOST_HEADER) {
    throw new Error(
      'IDENTITY_MACHINE_TOKEN_URL / IDENTITY_MACHINE_HOST_HEADER are not configured. ' +
        'They are injected by the compose identity wiring for inter-service callers.',
    );
  }
  const creds = loadMachineCredentials();
  const body = new URLSearchParams({
    grant_type: 'client_credentials',
    scope: `openid ${creds.audience}`,
  });
  const basic = Buffer.from(`${creds.clientId}:${creds.clientSecret}`).toString('base64');
  const response = await fetch(MACHINE_TOKEN_URL, {
    method: 'POST',
    headers: {
      Authorization: `Basic ${basic}`,
      'Content-Type': 'application/x-www-form-urlencoded',
      Host: MACHINE_HOST_HEADER,
    },
    body,
  });
  if (response.status !== 200) {
    const text = await response.text();
    throw new Error(
      `Failed to acquire Zitadel machine token via client_credentials (HTTP ${response.status}): ${text.slice(0, 300)}.`,
    );
  }
  const payload = (await response.json()) as Record<string, unknown>;
  const token = payload.access_token;
  if (typeof token !== 'string' || !token) {
    throw new Error("Zitadel token response did not contain an 'access_token'.");
  }
  const expiresIn = typeof payload.expires_in === 'number' ? payload.expires_in : 0;
  cachedToken = token;
  cachedExpiry = decodeTokenExpiry(token) || Date.now() / 1000 + expiresIn;
  return token;
}

export async function acquireServiceCredential(audience: string): Promise<string> {
  // Docker/self-host: the platform machine identity is a Zitadel service account.
  // The minted token is audience-scoped to the machine project and authenticates
  // to every peer, so the per-callee audience argument is not used here.
  void audience;
  return acquireZitadelMachineToken();
}
